-- MySQL-specific syntax: JSON, FULLTEXT, index hints, variables, SHOW, etc.
SELECT JSON_EXTRACT(payload, '$.user.id') AS uid FROM events;
SELECT payload->'$.name' AS n, payload->>'$.email' AS e FROM events;
SELECT JSON_UNQUOTE(JSON_EXTRACT(payload, '$.name')) FROM events WHERE JSON_CONTAINS(payload, '"x"', '$.tags');
SELECT JSON_OBJECT('id', id, 'name', name) FROM users;
SELECT JSON_ARRAYAGG(name) FROM users;
SELECT JSON_OBJECTAGG(k, v) FROM user_settings GROUP BY user_id;
SELECT * FROM events WHERE payload->>'$.type' = 'click' AND payload->'$.n' > 3;
UPDATE events SET payload = JSON_SET(payload, '$.seen', TRUE) WHERE id = 1;
SELECT jt.* FROM events, JSON_TABLE(payload, '$.items[*]' COLUMNS (id INT PATH '$.id', name VARCHAR(50) PATH '$.name')) AS jt;
SELECT * FROM docs WHERE MATCH(title, body) AGAINST ('database' IN NATURAL LANGUAGE MODE);
SELECT *, MATCH(body) AGAINST ('+mysql -oracle' IN BOOLEAN MODE) AS score FROM docs WHERE MATCH(body) AGAINST ('+mysql -oracle' IN BOOLEAN MODE);
SELECT * FROM docs WHERE MATCH(body) AGAINST ('query expansion' WITH QUERY EXPANSION);
SELECT * FROM users USE INDEX (idx_name) WHERE name = 'x';
SELECT * FROM users FORCE INDEX (PRIMARY) WHERE id > 5;
SELECT * FROM users IGNORE INDEX (idx_a, idx_b) WHERE a = 1;
SELECT * FROM users USE INDEX FOR ORDER BY (idx_created) ORDER BY created_at;
SELECT /*+ MAX_EXECUTION_TIME(1000) */ * FROM big_table;
SELECT /*! SQL_NO_CACHE */ * FROM t;
SELECT @rownum := @rownum + 1 AS rn, t.* FROM t, (SELECT @rownum := 0) r;
SET @a = 1, @b := 2;
SET @total = (SELECT COUNT(*) FROM users);
SET NAMES utf8mb4;
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION';
SET GLOBAL max_connections = 500;
SET autocommit = 0;
SET FOREIGN_KEY_CHECKS = 0;
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
SELECT @@version, @@session.sql_mode, @@global.max_connections;
SHOW TABLES;
SHOW FULL TABLES FROM app LIKE 'user%';
SHOW COLUMNS FROM users;
SHOW CREATE TABLE users;
SHOW INDEX FROM users;
SHOW DATABASES;
SHOW VARIABLES LIKE 'max_%';
SHOW STATUS LIKE 'Threads%';
SHOW PROCESSLIST;
SHOW FULL PROCESSLIST;
SHOW ENGINE INNODB STATUS;
SHOW WARNINGS;
SHOW TABLE STATUS LIKE 'users';
DESCRIBE users;
DESC users;
EXPLAIN SELECT * FROM users WHERE id = 1;
EXPLAIN FORMAT=JSON SELECT * FROM users;
EXPLAIN ANALYZE SELECT * FROM users;
USE app;
START TRANSACTION;
BEGIN;
COMMIT;
ROLLBACK;
SAVEPOINT sp1;
ROLLBACK TO SAVEPOINT sp1;
RELEASE SAVEPOINT sp1;
LOCK TABLES users WRITE, orders READ;
UNLOCK TABLES;
ANALYZE TABLE users;
OPTIMIZE TABLE users;
CHECK TABLE users;
KILL 123;
FLUSH PRIVILEGES;
LOAD DATA INFILE '/tmp/data.csv' INTO TABLE users FIELDS TERMINATED BY ',' ENCLOSED BY '"' LINES TERMINATED BY '\n' IGNORE 1 LINES (name, email);
SELECT CONVERT(x USING utf8mb4), CAST(y AS CHAR CHARACTER SET utf8mb4), CAST(z AS UNSIGNED), CAST(d AS DECIMAL(10,2)), CAST(s AS JSON) FROM t;
SELECT x COLLATE utf8mb4_bin FROM t WHERE name = _utf8mb4'abc' COLLATE utf8mb4_unicode_ci;
SELECT * FROM t WHERE a <=> NULL AND b REGEXP '^[a-z]+$' AND c RLIKE 'x' AND d DIV 3 = 1 AND e MOD 2 = 0 AND f XOR g;
SELECT 1 FROM DUAL;
SELECT 'it''s', "dq", 0x1F, X'4D', b'101', 1e3, .5;
SELECT BINARY name FROM t;
SELECT INTERVAL(5, 1, 10, 20);
SELECT CONCAT_WS(',', a, b), SUBSTRING_INDEX(email, '@', -1), FIND_IN_SET('a', 'a,b'), UUID(), RAND(), LAST_INSERT_ID();
SELECT EXTRACT(YEAR FROM created_at), EXTRACT(YEAR_MONTH FROM created_at) FROM t;
SELECT STR_TO_DATE('01/02/2024', '%d/%m/%Y'), FROM_UNIXTIME(1700000000), UNIX_TIMESTAMP('2024-01-01');
